#!/usr/bin/env bash
# fix-worker-fork.sh — worker children inherited the parent's asyncpg pool sockets,
# so concurrent tasks crashed with "another operation is in progress" and uploads
# stayed in "processing". Deploys the worker_process_init fix, rebuilds, and
# re-processes all stuck rows inline.
set -euo pipefail

cd /opt/wedding-app/backend/src/workers
cp media_processing.py media_processing.py.bak 2>/dev/null || true
base64 -d > media_processing.py <<'B64_MP'

B64_MP

echo "== Sanity check =="
grep -cF 'worker_process_init' media_processing.py

echo "== Rebuilding backend + worker (a few minutes) =="
cd /opt/wedding-app/infra
docker compose -f docker-compose.prod.yml build backend worker
docker compose -f docker-compose.prod.yml up -d backend worker
docker compose -f docker-compose.prod.yml restart nginx
sleep 15

echo "== Health =="
curl -sk https://localhost:8443/api/v1/health && echo

echo "== Re-processing stuck media rows (ids stuck at processing/pending) =="
docker compose -f docker-compose.prod.yml exec -T backend uv run python - <<'PYEOF'
import asyncio
from sqlalchemy import select
from sqlalchemy.ext.asyncio import AsyncSession, create_async_engine

from src.config import get_settings
from src.models.media import Media
from src.workers.media_processing import process_media


async def main() -> None:
    engine = create_async_engine(get_settings().database_url)
    async with AsyncSession(engine) as s:
        rows = (await s.execute(
            select(Media).where(Media.status.in_(["failed", "processing", "pending"]))
        )).scalars().all()
        if not rows:
            print("no stuck rows — all clear")
            return
        for m in rows:
            m.status = "processing"
            await process_media(s, m)
            await s.commit()
            await s.refresh(m)
            print(f"  id={m.id} ({m.original_filename}) -> {m.status}")


asyncio.run(main())
PYEOF

echo ""
echo "== Worker log after restart (expect clean start, no InterfaceError) =="
docker compose -f docker-compose.prod.yml logs worker --tail 15 2>&1 | tail -10

echo ""
echo "DONE. Refresh the gallery — all photos should now appear."